import java.io.InputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Arrays;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                e.printStackTrace();
            }
            return buflen > 0;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            return -1;
        }

        public boolean hasNext() {
            while (hasNextByte() && buffer[ptr] <= ' ') ptr++;
            return hasNextByte();
        }

        public int nextInt() {
            int c = readByte();
            while (c <= ' ') {
                if (c == -1) return -1;
                c = readByte();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = readByte();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return res * sgn;
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        if (!sc.hasNext()) return;

        int n = sc.nextInt();

        int[] head = new int[n + 1];
        Arrays.fill(head, -1);

        int maxEdges = 600005;
        int[] to = new int[maxEdges];
        int[] next = new int[maxEdges];
        int edgeCount = 0;

        for (int i = 1; i <= n; i++) {
            int m = sc.nextInt();
            for (int j = 0; j < m; j++) {
                int neighbor = sc.nextInt();
                to[edgeCount] = neighbor;
                next[edgeCount] = head[i];
                head[i] = edgeCount++;
            }
        }

        int[] color = new int[n + 1];
        int[] queue = new int[n + 1];

        for (int start = 1; start <= n; start++) {
            if (color[start] != 0) continue;

            color[start] = 1;
            int qHead = 0;
            int qTail = 0;
            queue[qTail++] = start;

            while (qHead < qTail) {
                int u = queue[qHead++];
                int nextColor = (color[u] == 1) ? 2 : 1;

                for (int e = head[u]; e != -1; e = next[e]) {
                    int v = to[e];
                    if (color[v] == 0) {
                        color[v] = nextColor;
                        queue[qTail++] = v;
                    }
                }
            }
        }

        PrintWriter out = new PrintWriter(System.out);

        boolean first = true;
        for (int i = 1; i <= n; i++) {
            if (color[i] == 1) {
                if (!first) out.print(' ');
                out.print(i);
                first = false;
            }
        }
        out.println();

        first = true;
        for (int i = 1; i <= n; i++) {
            if (color[i] == 2) {
                if (!first) out.print(' ');
                out.print(i);
                first = false;
            }
        }
        out.println();

        out.flush();
    }
}
